#include "model.hpp"
namespace pe {
void Body::elapse(){hunger=std::min(100.,hunger+.7);thirst=std::min(100.,thirst+1);fatigue=std::min(100.,fatigue+.15);if(hunger>=90||thirst>=90)health=std::max(0.,health-1);}
double Experience::efficiency(bool farm,double joy)const{double x=farm?farming:crafting;return (1+.4*x/(x+30))*(.97+joy*.0006);}
}
namespace pe::life {
void move(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);const auto& destination=location(s,c.target);require(p.journey.route==0,"Use journey commands while on a route");require(destination.region>0&&destination.region==location(s,p.location).region,"Direct move is local only; use travel between regions");require(p.location!=c.target,"Already at destination");start(s,p,ActivityKind::Move,c.target,1);emit(s,p.name+" departing toward "+location(s,c.target).name,{p.id});}
void meal(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);require(c.option==0||c.option==1,"Meal option must be0 or1");int n=c.option+1;require(p.account.inventory[Good::Food]>=n,"Meal requires own food; buy or acquire it first");start(s,p,ActivityKind::Meal,p.location,c.option?3:1,c.option);p.account.inventory[Good::Food]-=n;p.activity.reserved[Good::Food]=n;emit(s,p.name+" preparing "+(c.option?std::string("enjoyable"):std::string("simple"))+" meal; food reserved",{p.id});}
void drink(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);require(c.option==0||c.option==1,"Drink mode well0/inventory1");if(c.option==0){require(location(s,p.location).kind==SiteKind::Well,"Must visit public well");auto&well=location(s,p.location);require(well.stock[Good::Water]>0,"Well has no water");--well.stock[Good::Water];}else {require(p.account.inventory[Good::Water]>0,"No own water to drink");--p.account.inventory[Good::Water];}start(s,p,ActivityKind::Drink,p.location,1,c.option);p.activity.reserved[Good::Water]=1;emit(s,p.name+(c.option?" used1 own water":" drew1 public water"),{p.id});}
void rest(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);auto&l=location(s,p.location);require(contracts::residence(s,p.id,l.id),"No residence right at this location");start(s,p,ActivityKind::Rest,l.id,3);emit(s,p.name+(p.journey.route?" chose roadside rest":" started rest at lawful residence"),{p.id});}
void advance(State&s,Person&p){auto&a=p.activity;if(p.body.health<=0){cancel_activity(s,p.id,"health exhausted");return;}a.progress+=1;if(a.kind==ActivityKind::Rest||a.kind==ActivityKind::Care)p.body.fatigue=std::max(0.,p.body.fatigue-(p.journey.route?4:8));if(a.progress<a.required)return;
 Activity done=a;if(done.kind!=ActivityKind::Collect)for(int i=0;i<goods;++i)s.consumed.units[i]+=done.reserved.units[i];p.activity={};switch(done.kind){case ActivityKind::Move:p.location=done.target;observe(s,p.id);break;case ActivityKind::Meal:p.body.hunger=std::max(0.,p.body.hunger-35);p.body.joy=std::min(100.,p.body.joy+(done.option?10:2));emit(s,p.name+" ate prepared meal; hunger-35, joy+"+std::to_string(done.option?10:2),{p.id});break;case ActivityKind::Drink:p.body.thirst=std::max(0.,p.body.thirst-45);emit(s,p.name+" drank1 water; thirst-45",{p.id});break;case ActivityKind::Collect:p.account.inventory[Good::Water]+=done.reserved[Good::Water];emit(s,p.name+" collected1 water into own inventory",{p.id});break;case ActivityKind::Care:if(p.body.hunger<80&&p.body.thirst<80){p.body.health=std::min(100.,p.body.health+5);emit(s,p.name+" completed care with food/water/rest; health+5",{p.id});}else emit(s,p.name+" care completed but deprivation prevents health recovery",{p.id});break;case ActivityKind::Rest:emit(s,p.name+" completed rest; fatigue reduced over30 minutes",{p.id});break;default:throw RuleError("Invalid life activity");}}
}

namespace pe::life {
void collect(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);require(location(s,p.location).kind==SiteKind::Well,"Collect water at public well");auto& well=location(s,p.location);require(well.stock[Good::Water]>0,"Well has no water");--well.stock[Good::Water];start(s,p,ActivityKind::Collect,p.location,1);p.activity.reserved[Good::Water]=1;emit(s,p.name+" reserved1 water for collection",{p.id});}
void care(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);require(contracts::residence(s,p.id,p.location),"Care requires lawful residence");require(p.body.health<100,"Health already full");require(p.account.inventory[Good::Food]>=1&&p.account.inventory[Good::Water]>=1,"Care requires own food1 and water1");--p.account.inventory[Good::Food];--p.account.inventory[Good::Water];start(s,p,ActivityKind::Care,p.location,6);p.activity.reserved[Good::Food]=1;p.activity.reserved[Good::Water]=1;emit(s,p.name+" chose care; food1/water1 and60 minutes committed",{p.id});}
}
